            fb_prepared_row_draw(c->x,c->y,p,y-c->y,c->left,c->right,c->color);
        }
    }else {
        for(unsigned i=0;i<count;i++) {
            const struct fb_prepared_clip *c=&commands[i];
            if(y>=c->top && y<c->bottom)
                fb_prepared_row_draw(c->x,c->y,p,y-c->y,c->left,c->right,c->color);
        }
    }
}
