/* Bounded layout cache; keeps separate owned glyphs and preserves draw order. */
#ifndef FB_TEXT_LAYOUT_H
#define FB_TEXT_LAYOUT_H
const void *fb_font_identity(void);
#define FB_LAYOUT_SLOTS 8
#define FB_LAYOUT_GLYPHS 128
#define FB_LAYOUT_TEXT_BYTES 256
#define FB_LAYOUT_MAX_BYTES (64U*1024U)
struct fb_glyph_row_range {uint16_t left,right;};
struct fb_layout_glyph {fb_image *image;fb_font_info info;int offset;struct fb_glyph_row_range *ranges;};
struct fb_layout_entry {
    const void *font;
    int size,count;
    char text[FB_LAYOUT_TEXT_BYTES+1];
    struct fb_layout_glyph *glyphs;
};
static struct fb_layout_entry fb_layouts[FB_LAYOUT_SLOTS];
static unsigned fb_layout_next;
static int fb_layout_cleanup_registered;
static void fb_layout_release(struct fb_layout_entry *entry)
{
    for(int i=0;i<entry->count;++i) {
        fb_free_image(entry->glyphs[i].image);free(entry->glyphs[i].ranges);
    }
    free(entry->glyphs);
    memset(entry,0,sizeof(*entry));
}
static void fb_layout_cleanup(void)
{
    for(int i=0;i<FB_LAYOUT_SLOTS;++i) fb_layout_release(&fb_layouts[i]);
}
static struct fb_layout_entry *fb_layout_get(const char *text,int size)
{
    const void *font=fb_font_identity();
    if(!font || size<=0 || size>128) return NULL;
    size_t length=strlen(text);
    if(!length || length>FB_LAYOUT_TEXT_BYTES) return NULL;
    for(int i=0;i<FB_LAYOUT_SLOTS;++i) {
        struct fb_layout_entry *e=&fb_layouts[i];
        if(e->glyphs && e->font==font && e->size==size && !strcmp(e->text,text)) return e;
    }
    struct fb_layout_entry e={0};
    e.glyphs=calloc(FB_LAYOUT_GLYPHS,sizeof(*e.glyphs));
    if(!e.glyphs) return NULL;
    e.font=font;e.size=size;memcpy(e.text,text,length+1);
    size_t index=0,total_bytes=0;
    int64_t advance=0;
    while(index<length && e.count<FB_LAYOUT_GLYPHS) {
        fb_font_info info={0};
        fb_image *image=fb_read_font_image(text+index,size,&info);
        if(!image || info.bytes<=0 || (size_t)info.bytes>length-index) {
            fb_free_image(image);fb_layout_release(&e);return NULL;
        }
        size_t bytes=(size_t)image->line_byte*image->pixel_h;
        if(bytes>FB_LAYOUT_MAX_BYTES-total_bytes || advance<INT_MIN || advance>INT_MAX) {
            fb_free_image(image);fb_layout_release(&e);return NULL;
        }
        struct fb_glyph_row_range *ranges=NULL;
        size_t range_bytes=(size_t)image->pixel_h*sizeof(*ranges);
        if(image->color_type==FB_COLOR_ALPHA_8 && image->content && image->pixel_w>0 && image->pixel_h>0 && image->pixel_w<=UINT16_MAX
           && range_bytes<=FB_LAYOUT_MAX_BYTES-total_bytes-bytes) {
            ranges=calloc((size_t)image->pixel_h,sizeof(*ranges));
            if(ranges) {
                for(int row=0;row<image->pixel_h;row++) {
                    const unsigned char *p=(const unsigned char *)image->content+(size_t)row*image->line_byte;
                    int left=0,right=image->pixel_w;
                    while(left<right && !p[left])left++;
                    while(right>left && !p[right-1])right--;
                    ranges[row]=(struct fb_glyph_row_range){(uint16_t)left,(uint16_t)right};
                }
                total_bytes+=range_bytes;
            }
        }
        e.glyphs[e.count++]=(struct fb_layout_glyph){image,info,(int)advance,ranges};
        total_bytes+=bytes;index+=(size_t)info.bytes;advance+=info.advance_x;
    }
    if(index!=length) {fb_layout_release(&e);return NULL;}
    if(!fb_layout_cleanup_registered) {
        if(atexit(fb_layout_cleanup)) {fb_layout_release(&e);return NULL;}
        fb_layout_cleanup_registered=1;
    }
    struct fb_layout_entry *slot=&fb_layouts[fb_layout_next];
    fb_layout_release(slot);*slot=e;
    fb_layout_next=(fb_layout_next+1)%FB_LAYOUT_SLOTS;
    return slot;
}
static void fb_layout_draw_glyph(int x,int y,const struct fb_layout_glyph *g,int color)
{
    fb_image *image=g->image;
    if(!g->ranges){fb_draw_image(x,y,image,color);return;}
    if(!image->content || image->pixel_w<=0 || image->pixel_h<=0)return;
    int64_t left=x,top=y,right=(int64_t)x+image->pixel_w,bottom=(int64_t)y+image->pixel_h;
    if(left<0)left=0;
    if(top<0)top=0;
    if(right>SCREEN_WIDTH)right=SCREEN_WIDTH;
    if(bottom>SCREEN_HEIGHT)bottom=SCREEN_HEIGHT;
    if(left>=right || top>=bottom)return;
    _begin_draw((int)left,(int)top,(int)(right-left),(int)(bottom-top));
    int clip_left=(int)(left-x),clip_right=(int)(right-x);
    for(int row=(int)top;row<(int)bottom;row++) {
        int source_y=(int)((int64_t)row-y);
        int l=g->ranges[source_y].left,r=g->ranges[source_y].right;
        if(l<clip_left)l=clip_left;
        if(r>clip_right)r=clip_right;
        if(l<r)fb_alpha_row((uint32_t *)(DRAW_BUF+row*SCREEN_WIDTH+(int)((int64_t)x+l)),
            (const unsigned char *)image->content+(size_t)source_y*image->line_byte+l,r-l,(uint32_t)color);
    }
}
void fb_draw_text(int x,int y,char *text,int font_size,int color)
{
    if(!text) return;
    struct fb_layout_entry *layout=fb_layout_get(text,font_size);
    if(layout) {
        for(int i=0;i<layout->count;++i) {
            const struct fb_layout_glyph *g=&layout->glyphs[i];
            fb_layout_draw_glyph(x+g->offset+g->info.left,y-g->info.top,g,color);
        }
        return;
    }
    size_t i=0,length=strlen(text);
    while(i<length) {
        fb_font_info info={0};
        fb_image *image=fb_read_font_image(text+i,font_size,&info);
        if(!image) break;
        if(info.bytes<=0 || (size_t)info.bytes>length-i) {fb_free_image(image);break;}
        fb_draw_image(x+info.left,y-info.top,image,color);
        fb_free_image(image);x+=info.advance_x;i+=(size_t)info.bytes;
    }
}
#endif

/* Bounded layout cache; keeps separate owned glyphs and preserves draw order. */
#ifndef FB_TEXT_LAYOUT_H
#define FB_TEXT_LAYOUT_H
const void *fb_font_identity(void);
#define FB_LAYOUT_SLOTS 8
#define FB_LAYOUT_GLYPHS 128
#define FB_LAYOUT_TEXT_BYTES 256
#define FB_LAYOUT_MAX_BYTES (64U*1024U)
struct fb_glyph_row_range {uint16_t left,right;};
struct fb_layout_glyph {fb_image *image;fb_font_info info;int offset;struct fb_glyph_row_range *ranges;};
struct fb_layout_entry {
    const void *font;
    int size,count;
    char text[FB_LAYOUT_TEXT_BYTES+1];
    struct fb_layout_glyph *glyphs;
};
static struct fb_layout_entry fb_layouts[FB_LAYOUT_SLOTS];
static unsigned fb_layout_next;
static int fb_layout_cleanup_registered;
static void fb_layout_release(struct fb_layout_entry *entry)
{
    for(int i=0;i<entry->count;++i) {
        fb_free_image(entry->glyphs[i].image);free(entry->glyphs[i].ranges);
    }
    free(entry->glyphs);
    memset(entry,0,sizeof(*entry));
}
static void fb_layout_cleanup(void)
{
    for(int i=0;i<FB_LAYOUT_SLOTS;++i) fb_layout_release(&fb_layouts[i]);
}
static struct fb_layout_entry *fb_layout_get(const char *text,int size)
{
    const void *font=fb_font_identity();
    if(!font || size<=0 || size>128) return NULL;
    size_t length=strlen(text);
    if(!length || length>FB_LAYOUT_TEXT_BYTES) return NULL;
    for(int i=0;i<FB_LAYOUT_SLOTS;++i) {
        struct fb_layout_entry *e=&fb_layouts[i];
        if(e->glyphs && e->font==font && e->size==size && !strcmp(e->text,text)) return e;
    }
    struct fb_layout_entry e={0};
    e.glyphs=calloc(FB_LAYOUT_GLYPHS,sizeof(*e.glyphs));
    if(!e.glyphs) return NULL;
    e.font=font;e.size=size;memcpy(e.text,text,length+1);
    size_t index=0,total_bytes=0;
    int64_t advance=0;
    while(index<length && e.count<FB_LAYOUT_GLYPHS) {
        fb_font_info info={0};
        fb_image *image=fb_read_font_image(text+index,size,&info);
        if(!image || info.bytes<=0 || (size_t)info.bytes>length-index) {
            fb_free_image(image);fb_layout_release(&e);return NULL;
        }
        size_t bytes=(size_t)image->line_byte*image->pixel_h;
        if(bytes>FB_LAYOUT_MAX_BYTES-total_bytes || advance<INT_MIN || advance>INT_MAX) {
            fb_free_image(image);fb_layout_release(&e);return NULL;
        }
        struct fb_glyph_row_range *ranges=NULL;
        #ifndef FB_DISABLE_TEXT_RANGES
        size_t range_bytes=(size_t)image->pixel_h*sizeof(*ranges);
        if(image->color_type==FB_COLOR_ALPHA_8 && image->content && image->pixel_w>0 && image->pixel_h>0 && image->pixel_w<=UINT16_MAX
           && range_bytes<=FB_LAYOUT_MAX_BYTES-total_bytes-bytes) {
            ranges=calloc((size_t)image->pixel_h,sizeof(*ranges));
            if(ranges) {
                for(int row=0;row<image->pixel_h;row++) {
                    const unsigned char *p=(const unsigned char *)image->content+(size_t)row*image->line_byte;
                    int left=0,right=image->pixel_w;
                    while(left<right && !p[left])left++;
                    while(right>left && !p[right-1])right--;
                    ranges[row]=(struct fb_glyph_row_range){(uint16_t)left,(uint16_t)right};
                }
                total_bytes+=range_bytes;
            }
        }
        #endif
        e.glyphs[e.count++]=(struct fb_layout_glyph){image,info,(int)advance,ranges};
        total_bytes+=bytes;index+=(size_t)info.bytes;advance+=info.advance_x;
    }
    if(index!=length) {fb_layout_release(&e);return NULL;}
    if(!fb_layout_cleanup_registered) {
        if(atexit(fb_layout_cleanup)) {fb_layout_release(&e);return NULL;}
        fb_layout_cleanup_registered=1;
    }
    struct fb_layout_entry *slot=&fb_layouts[fb_layout_next];
    fb_layout_release(slot);*slot=e;
    fb_layout_next=(fb_layout_next+1)%FB_LAYOUT_SLOTS;
    return slot;
}
static void fb_layout_draw_glyph(int x,int y,const struct fb_layout_glyph *g,int color)
{
    fb_image *image=g->image;
    if(!g->ranges){fb_draw_image(x,y,image,color);return;}
    if(!image->content || image->pixel_w<=0 || image->pixel_h<=0)return;
    int64_t left=x,top=y,right=(int64_t)x+image->pixel_w,bottom=(int64_t)y+image->pixel_h;
    if(left<0)left=0;
    if(top<0)top=0;
    if(right>SCREEN_WIDTH)right=SCREEN_WIDTH;
    if(bottom>SCREEN_HEIGHT)bottom=SCREEN_HEIGHT;
    if(left>=right || top>=bottom)return;
    _begin_draw((int)left,(int)top,(int)(right-left),(int)(bottom-top));
    int clip_left=(int)(left-x),clip_right=(int)(right-x);
    for(int row=(int)top;row<(int)bottom;row++) {
        int source_y=(int)((int64_t)row-y);
        int l=g->ranges[source_y].left,r=g->ranges[source_y].right;
        if(l<clip_left)l=clip_left;
        if(r>clip_right)r=clip_right;
        if(l<r)fb_alpha_row((uint32_t *)(DRAW_BUF+row*SCREEN_WIDTH+(int)((int64_t)x+l)),
            (const unsigned char *)image->content+(size_t)source_y*image->line_byte+l,r-l,(uint32_t)color);
    }
}
void fb_draw_text(int x,int y,char *text,int font_size,int color)
{
    if(!text) return;
    struct fb_layout_entry *layout=fb_layout_get(text,font_size);
    if(layout) {
        for(int i=0;i<layout->count;++i) {
            const struct fb_layout_glyph *g=&layout->glyphs[i];
            fb_layout_draw_glyph(x+g->offset+g->info.left,y-g->info.top,g,color);
        }
        return;
    }
    size_t i=0,length=strlen(text);
    while(i<length) {
        fb_font_info info={0};
        fb_image *image=fb_read_font_image(text+i,font_size,&info);
        if(!image) break;
        if(info.bytes<=0 || (size_t)info.bytes>length-i) {fb_free_image(image);break;}
        fb_draw_image(x+info.left,y-info.top,image,color);
        fb_free_image(image);x+=info.advance_x;i+=(size_t)info.bytes;
    }
}
#endif

/* Called only after course timers end. Retain all original drawing work. */
#include <stdio.h>
#include <time.h>
#include <stdint.h>
#undef fb_update
void fb_update_impl(void);
void fb_update(void)
{
    struct timespec before, after;
    clock_gettime(CLOCK_MONOTONIC, &before);
    fb_update_impl();
    clock_gettime(CLOCK_MONOTONIC, &after);
    int64_t us = (int64_t)(after.tv_sec-before.tv_sec)*1000000
               + (after.tv_nsec-before.tv_nsec)/1000;
    fprintf(stderr, "FLUSH_US=%lld\n", (long long)us);
}

"""Read-only checks on the Orange Pi. Does not stop the desktop or change Bluetooth."""
from pathlib import Path
import argparse, array, fcntl, json, os, shutil, subprocess, sys

def touchscreen_info(path):
    descriptor=os.open(path,os.O_RDONLY|os.O_NONBLOCK)
    try:
        axes={}
        for name,code in (("slot",0x2f),("x",0x35),("y",0x36)):
            values=array.array("i",[0]*6)
            request=(2<<30)|(24<<16)|(ord("E")<<8)|(0x40+code)
            fcntl.ioctl(descriptor,request,values,True)
            axes[name]={"minimum":values[1],"maximum":values[2]}
        return {"path":str(path),"axes":axes}
    finally:os.close(descriptor)

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--project",required=True)
    parser.add_argument("--lab",choices=("lab2","lab3","lab4","lab5_bt","test"),required=True)
    parser.add_argument("--touch");parser.add_argument("--serial",default="/dev/rfcomm0")
    parser.add_argument("--headless",action="store_true")
    args=parser.parse_args();project=Path(args.project).resolve(strict=True)
    failures=[];info={"project":str(project),"lab":args.lab,"checksAreReadOnly":True}
    binary=project/"out"/args.lab
    if not binary.is_file() or not os.access(binary,os.X_OK):failures.append(f"Build executable first: {binary}")
    if not args.headless:
        try:
            descriptor=os.open("/dev/fb0",os.O_RDONLY)
            try:
                values=array.array("I",[0]*40);fcntl.ioctl(descriptor,0x4600,values,True)
            finally:os.close(descriptor)
            info["framebuffer"]={"width":values[0],"height":values[1],"bitsPerPixel":values[6],
                "red":[values[8],values[9]],"green":[values[11],values[12]],"blue":[values[14],values[15]]}
            if (values[0],values[1],values[6],values[8],values[9],values[11],values[12],values[14],values[15])!=(1024,600,32,16,8,8,8,0,8):
                failures.append("Framebuffer format differs from course constants; adjust mode/code before running.")
        except OSError as error:failures.append(f"Framebuffer unavailable: {error}")
        if not os.access("/dev/fb0",os.R_OK|os.W_OK):failures.append("Framebuffer is not readable/writable.")
        for name in ("font.ttc", "test.jpg", "test.png"):
            if args.lab in ("lab3","test") or name=="font.ttc":
                if not (project/"out"/name).is_file():failures.append(f"Missing asset: out/{name}")
        if args.lab in ("lab4","lab5_bt"):
            devices=[]
            for path in ([Path(args.touch)] if args.touch else sorted(Path("/dev/input").glob("event*"))):
                try:devices.append(touchscreen_info(path))
                except OSError:continue
            info["protocolBTouchscreens"]=devices
            if not devices:failures.append("No protocol-B touchscreen detected; check its USB touch cable.")
            if len(devices)>1 and not args.touch:failures.append("Multiple touchscreens; choose --touch /dev/input/eventN explicitly.")
        if shutil.which("systemctl"):
            check=subprocess.run(["systemctl","is-active","display-manager"],capture_output=True,text=True)
            info["displayManager"]=check.stdout.strip()
            if check.returncode==0:
                failures.append("Board desktop is active. Follow PPT 37-38 to stop the board desktop before framebuffer experiments.")
    if args.lab=="lab5_bt":
        info["bluetoothTools"]={name:shutil.which(name) for name in ("bluetoothctl","rfcomm","sdptool","hciconfig")}
        if not Path(args.serial).exists():failures.append(f"Pair/connect the Bluetooth client and keep rfcomm watch running: {args.serial} absent.")
    info["problems"]=failures;print(json.dumps(info,ensure_ascii=False,indent=2))
    return bool(failures)
if __name__=="__main__":sys.exit(main())

"""Generate a separate, synchronous high-resolution course diagnostic.

The original source is never edited. Compile the generated main instead of the
original main with exactly the same remaining sources/flags/assets. Diagnostic
numbers must not be silently substituted for the unchanged course score.
"""
from pathlib import Path
import argparse
import hashlib
import json
import re

PRELUDE = r'''
#include <stdint.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#ifndef LAB3_DIAG_CLOCK_READ
#define LAB3_DIAG_CLOCK_READ clock_gettime
#endif
static uint64_t lab3_diag_times[14];
static unsigned lab3_diag_count;
static int32_t lab3_diag_clock(void)
{
    struct timespec ts;
    if (LAB3_DIAG_CLOCK_READ(CLOCK_MONOTONIC, &ts) != 0) {
        perror("diagnostic clock_gettime"); exit(EXIT_FAILURE);
    }
    uint64_t ns = (uint64_t)ts.tv_sec * UINT64_C(1000000000) + (uint64_t)ts.tv_nsec;
    if (lab3_diag_count >= 14) {
        fprintf(stderr,"Unexpected diagnostic timestamp count\n"); exit(EXIT_FAILURE);
    }
    lab3_diag_times[lab3_diag_count++] = ns;
    return (int32_t)(uint32_t)(ns / UINT64_C(1000000));
}
'''

SUFFIX = r'''
int main(int argc, char **argv)
{
    int rc = lab3_diag_course_main(argc, argv);
    if (rc != 0) return rc;
    if (lab3_diag_count != 14) {
        fprintf(stderr,"Incomplete diagnostic timestamps: %u\n", lab3_diag_count);
        return EXIT_FAILURE;
    }
    const char *names[7] = {"pixel","rect","line","jpg","png","font","text"};
    uint64_t total = 0;
    for (unsigned i = 0; i < 7; ++i) {
        uint64_t a = lab3_diag_times[i*2], b = lab3_diag_times[i*2+1];
        if (b < a) return EXIT_FAILURE;
        uint64_t elapsed = b-a;
        total += elapsed;
        printf("DIAGNOSTIC_STAGE_NS %s %" PRIu64 "\n", names[i], elapsed);
    }
    printf("DIAGNOSTIC_TOTAL_NS %" PRIu64 "\n", total);
    printf("DIAGNOSTIC_ONLY=1 includes_flush=0 includes_decode=0 includes_sleep=0\n");
    return rc;
}
'''


def generate(source, destination):
    source, destination = Path(source).resolve(), Path(destination).resolve()
    if source == destination or destination.exists():
        raise ValueError('Choose a new diagnostic output path; existing files are preserved')
    original = source.read_bytes()
    body = original.decode('utf-8-sig')
    body, count = re.subn(r'\btask_get_time\s*\(\s*\)', 'lab3_diag_clock()', body)
    if count != 14:
        raise ValueError('Expected exactly fourteen course timing calls, got %d' % count)
    body, count = re.subn(r'\bint\s+main\s*\(', 'static int lab3_diag_course_main(', body)
    if count != 1:
        raise ValueError('Expected exactly one int main definition')
    # The generated source can live outside test/. Resolve only observed quoted
    # local includes; no remote downloads or inferred project source files.
    def include(match):
        path = (source.parent / match.group(1)).resolve(strict=True)
        if '"' in str(path):
            raise ValueError('Unsupported quote in include path')
        return '#include "' + path.as_posix() + '"'
    body = re.sub(r'^\s*#include\s+"([^"\n]+)"\s*$', include, body, flags=re.M)
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(PRELUDE + '\n' + body + '\n' + SUFFIX, encoding='utf-8')
    assert source.read_bytes() == original
    metadata = {
        'source': str(source), 'sourceSHA256': hashlib.sha256(original).hexdigest(),
        'generated': str(destination), 'generatedSHA256': hashlib.sha256(destination.read_bytes()).hexdigest(),
        'originalSourceUnchanged': True, 'timingSites': 14,
        'clock': 'CLOCK_MONOTONIC', 'resolutionUnit': 'nanoseconds, not a guarantee of clock precision',
        'stageWorkUnchanged': True, 'timingInstrumentationChanged': True,
        'hardwareValidated': False, 'performanceMeasured': False,
        'scope': 'Seven original synchronous stage intervals; excludes original flush/decode/sleep',
    }
    destination.with_suffix(destination.suffix + '.json').write_text(
        json.dumps(metadata, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    return metadata


if __name__ == '__main__':
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--source', required=True)
    p.add_argument('--output', required=True)
    args = p.parse_args()
    print(json.dumps(generate(args.source, args.output), ensure_ascii=False, indent=2))

